package com.learnagent.skill;import com.learnagent.agent.AgentExecutionTracker;import com.learnagent.weekly.*;import org.springframework.ai.tool.annotation.Tool;import org.springframework.stereotype.Component;
@Component public class WeeklyReviewSkill{private final WeeklyReviewService service;private final AgentExecutionTracker tracker;public WeeklyReviewSkill(WeeklyReviewService service,AgentExecutionTracker tracker){this.service=service;this.tracker=tracker;}@Tool(description="Generate and save the current natural-week learning review from real tasks, quizzes, answers, and weak points.")public WeeklyReviewService.WeeklyReviewView generateWeeklyReview(){return tracker.execute("Weekly Review Skill","generateWeeklyReview",service::generate,review->"Generated "+review.status()+" weekly review");}@Tool(description="Read the latest saved weekly learning review, if one exists.")public WeeklyReviewService.WeeklyReviewView getLatestWeeklyReview(){return tracker.execute("Weekly Review Skill","getLatestWeeklyReview",service::latest,review->review==null?"No weekly review exists":"Loaded latest weekly review");}}
